results = {
    "q1": (["d3", "d7", "d1"], {"d1"}),
    "q2": (["d2", "d9", "d4"], {"d5"}),
    "q3": (["d8", "d6", "d2"], {"d8", "d6"}),
}
for k in (1, 3):
    hit = [len(set(top[:k]) & gold) / len(gold) for top, gold in results.values()]
    print(f"recall@{k} = {sum(hit)/len(hit):.2f}")
